SELECT p.name AS project_id, p.project_name, q.name AS quotation FROM `tabProject` p INNER JOIN `tabQuotation` q ON q.custom_project = p.name AND q.workflow_state = 'Confirmed' LEFT JOIN `tabSales Order` so ON so.project = p.name AND so.docstatus = 1 WHERE p.project_type = 'Bioman Production' AND p.status NOT IN ('Completed', 'Cancelled') AND p.owner = %s AND so.name IS NULL GROUP BY p.name, p.project_name, q.name ORDER BY p.modified DESC
